<?php
namespace Tests\Feature\InternalGames;
use Tests\TestCase;
use Tests\Support\BlackjackFixture;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use App\Models\{CmsGame,CmsUser,CmsUserTransaction,InternalGameSession};
class BlackjackHttpBoundaryTest extends TestCase {
 use DatabaseTransactions,BlackjackFixture;
 protected function setUp():void{parent::setUp();$this->withCredentials();$this->setupBlackjack('500.00',false);$this->vector();}
 private function login():void{$this->postJson('/cms/login',['email'=>$this->player->username,'password'=>'Blackjack-Local-927!'],['X-Requested-With'=>'XMLHttpRequest'])->assertJsonPath('status',200);$this->withCookie(config('session.cookie'),session()->getId());}
 private function launch(string $code='blackjack-classic',string $mode='real'):string{$r=$this->post('/cms/games/'.$code.'/launch',['playType'=>$mode]);$r->assertRedirect();$this->withCookie(config('session.cookie'),session()->getId());return basename($r->headers->get('Location'));}
 private function start(string $token):array{return ['sessionToken'=>$token,'betAmount'=>'10.00','requestKey'=>'native-bj-start'];}
 public function test_native_four_launch_modes_hit_stand_and_share_canonical_history():void{
  $this->login();foreach(['blackjack-classic','blackjack-salon']as $code)foreach(['demo','real']as $mode){$token=$this->launch($code,$mode);if($mode==='demo')$demoToken=$token;else $this->assertSame($demoToken,$token);$this->get('/cms/internal-games/play/'.$token)->assertOk()->assertSee('data-bj-theme="'.($code==='blackjack-classic'?'classic':'salon').'"',false);$before=$this->financeHash();$request=['sessionToken'=>$token,'betAmount'=>$code==='blackjack-classic'?'10.00':'25.00','requestKey'=>'native-start-'.$mode];$data=$this->postJson('/cms/internal-games/blackjack/start',$request)->assertOk()->json('data');$this->assertTrue($data['dealer']['cards'][1]['hidden']);$this->assertArrayNotHasKey('dealer_cards',$data['actionTimeline'][0]);$this->getJson('/cms/internal-games/blackjack/snapshot?sessionToken='.$token)->assertOk()->assertJsonPath('data.currentRound.roundId',$data['roundId']);$action=['sessionToken'=>$token,'roundId'=>$data['roundId'],'action'=>'hit','requestKey'=>'native-hit-'.$mode,'roundVersion'=>1];$hit=$this->postJson('/cms/internal-games/blackjack/action',$action)->assertOk()->json('data');$this->postJson('/cms/internal-games/blackjack/action',$action)->assertOk()->assertJsonPath('data.roundVersion',2);$action['action']='stand';$action['requestKey']='native-stand-'.$mode;$action['roundVersion']=2;$this->postJson('/cms/internal-games/blackjack/action',$action)->assertOk()->assertJsonPath('data.phase','resolved');$this->getJson('/cms/internal-games/blackjack/snapshot?sessionToken='.$token)->assertOk()->assertJsonCount($mode==='demo'?1:2,'data.history')->assertJsonPath('data.history.0.roundId',$data['roundId']);$this->assertNotSame($before,$this->financeHash());}$this->reconcileBlackjack();
 }
 public function test_server_rejects_forged_cards_wallet_result_version_key_and_other_round():void{
  $this->login();$token=$this->launch();$r=$this->postJson('/cms/internal-games/blackjack/start',$this->start($token))->assertOk()->json('data');$before=$this->financeHash();$base=['sessionToken'=>$token,'roundId'=>$r['roundId'],'action'=>'stand','requestKey'=>'forged-action','roundVersion'=>1];foreach(['result'=>['outcome'=>'win'],'remainingDeck'=>['AH'],'wallet_account_id'=>999,'balance'=>9999,'payoutTotal'=>9999]as $key=>$value)$this->postJson('/cms/internal-games/blackjack/action',$base+[$key=>$value])->assertUnprocessable();$bad=$base;$bad['requestKey']='key.with.dots';$this->postJson('/cms/internal-games/blackjack/action',$bad)->assertUnprocessable();$bad=$base;$bad['roundVersion']=100;$this->postJson('/cms/internal-games/blackjack/action',$bad)->assertConflict()->assertJsonPath('code','BLACKJACK_STALE_ACTION');$bad=$base;$bad['roundId']='another-users-round';$this->postJson('/cms/internal-games/blackjack/action',$bad)->assertNotFound();$this->assertSame($before,$this->financeHash());
 }
 public function test_expiry_maintenance_hidden_and_guest_real_boundaries():void{
  $this->post('/cms/games/blackjack-classic/launch',['playType'=>'real'])->assertForbidden();$this->login();$token=$this->launch();$data=$this->postJson('/cms/internal-games/blackjack/start',$this->start($token))->assertOk()->json('data');$s=InternalGameSession::where('session_token',$token)->firstOrFail();$before=$this->financeHash();$s->update(['expires_at'=>now()->subMinute()]);$this->postJson('/cms/internal-games/blackjack/action',['sessionToken'=>$token,'roundId'=>$data['roundId'],'action'=>'stand','requestKey'=>'expired-action','roundVersion'=>1])->assertGone();$token=$this->launch();$this->assertSame(1,InternalGameSession::count());$this->assertSame($before,$this->financeHash());$g=CmsGame::where('slug','blackjack-classic')->firstOrFail();$g->update(['is_maintenance'=>true]);$this->getJson('/cms/internal-games/blackjack/snapshot?sessionToken='.$token)->assertServiceUnavailable();$g->update(['is_maintenance'=>false,'status'=>'passive']);$this->get('/cms/games/blackjack-classic')->assertNotFound();$this->assertSame($before,$this->financeHash());
 }
}
